        foreach(array_keys($indexed) as $candidate){$c=(string)$candidate;$cl=pb_strtolower(ltrim($c,'/'));if($cl===$lower)return $c;if(str_ends_with($cl,'/'.$lower)||str_ends_with($lower,'/'.$cl))$suffix[]=$c;if(pb_strtolower(basename($c))===$base)$baseHits[]=$c;}
