    }
    private static function validateGeneratedContent(string $path,string $content):void{$ext=strtolower(pathinfo($path,PATHINFO_EXTENSION));if($ext==='php'){try{token_get_all($content,TOKEN_PARSE);}catch(Throwable){throw new RuntimeException('php_syntax_invalid:'.$path);}}elseif($ext==='json'){json_decode($content,true);if(json_last_error()!==JSON_ERROR_NONE)throw new RuntimeException('json_syntax_invalid:'.$path);}}
